/*
 * iOS launch images for the home-screen app (generated by
 * scripts/make-splash.sh). iOS ignores the manifest's background_color and
 * shows a white screen at launch unless a matching startup image exists.
 */

// CSS width × height × device pixel ratio (keep in sync with make-splash.sh).
const DEVICES: [number, number, number][] = [
	[440, 956, 3],
	[430, 932, 3],
	[428, 926, 3],
	[420, 912, 3],
	[414, 896, 3],
	[414, 896, 2],
	[414, 736, 3],
	[402, 874, 3],
	[393, 852, 3],
	[390, 844, 3],
	[375, 812, 3],
	[375, 667, 2],
	[360, 780, 3],
	[320, 568, 2],
	[1032, 1376, 2],
	[1024, 1366, 2],
	[834, 1210, 2],
	[834, 1194, 2],
	[820, 1180, 2],
	[810, 1080, 2],
	[768, 1024, 2],
	[744, 1133, 2],
];

export const splashLinks = DEVICES.flatMap(([width, height, ratio]) =>
	(["portrait", "landscape"] as const).map((orientation) => {
		const [w, h] =
			orientation === "portrait"
				? [width * ratio, height * ratio]
				: [height * ratio, width * ratio];
		return {
			rel: "apple-touch-startup-image",
			href: `/splash/${w}x${h}.png`,
			media: `(device-width: ${width}px) and (device-height: ${height}px) and (-webkit-device-pixel-ratio: ${ratio}) and (orientation: ${orientation})`,
		};
	}),
);
